1	//! Agent-facing output: TOON projections of command results and conversion of [`MonoklError`] into michi errors.
2	use std::collections::BTreeMap;
3	
4	use camino::Utf8Path;
5	use michi::toon::Value;
6	
7	use crate::error::MonoklError;
8	use crate::types::{Diagnostic, RankedBlock, SearchResponse};
9	
10	/// Maps `None` to [`Value::Null`], so a reader can tell an absent field from an empty string.
11	fn opt_cell(s: Option<&str>) -> Value {
12	    s.map_or(Value::Null, Value::from)
13	}
14	
15	const TRUNCATION_GUIDANCE: &str = "raise the cap or refine the query with +term or -term";
16	
17	/// The most matching lines a row's snippet shows.
18	const SNIPPET_LINES: usize = 3;
19	/// The most characters of one matching line a snippet shows.
20	const SNIPPET_LINE_CHARS: usize = 160;
21	
22	/// The lines of `block` that matched the query, numbered, so a reader often needs no second read of the file.
23	///
24	/// A line the signature column already shows is left out: one whose text lies inside the block's
25	/// [`signature_span`](crate::types::CodeBlock::signature_span). A variable or type alias has no signature, so its first
26	/// line is the best thing to show; so is a first line that says more than the signature, such as a decorator or the
27	/// start of an arrow function's body. At most [`SNIPPET_LINES`] lines appear, each cut to [`SNIPPET_LINE_CHARS`]
28	/// characters, and the lines beyond that are counted, not dropped silently.
29	fn snippet(block: &crate::types::CodeBlock) -> Option<String> {
30	    let mut lines = Vec::new();
31	    let mut start = block.span.start;
32	    for text in block.code.split('\n') {
33	        lines.push((start, text));
34	        start += text.len() + 1;
35	    }
36	    let mut shown: Vec<usize> = block
37	        .matched_lines
38	        .iter()
39	        .copied()
40	        .filter(|&line| line >= block.line_start && line - block.line_start < lines.len())
41	        .filter(|&line| {
42	            let (start, text) = lines[line - block.line_start];
43	            !block.signature_span.as_ref().is_some_and(|head| inside(head, start, text))
44	        })
45	        .collect();
46	    shown.sort_unstable();
47	    shown.dedup();
48	    let hidden = shown.len().saturating_sub(SNIPPET_LINES);
49	    let mut out: Vec<String> = shown
50	        .iter()
51	        .take(SNIPPET_LINES)
52	        .map(|&line| {
53	            let text = lines[line - block.line_start].1.trim();
54	            let mut chars = text.chars();
55	            let head: String = chars.by_ref().take(SNIPPET_LINE_CHARS).collect();
56	            let ellipsis = if chars.next().is_some() { "…" } else { "" };
57	            format!("{line}: {head}{ellipsis}")
58	        })
59	        .collect();
60	    if out.is_empty() {
61	        return None;
62	    }
63	    if hidden > 0 {
64	        out.push(format!("...and {hidden} more matching {}", if hidden == 1 { "line" } else { "lines" }));
65	    }
66	    Some(out.join("\n"))
67	}
68	
69	/// Whether the text of a line, which starts at byte `start`, holds something and lies wholly inside `head`.
70	fn inside(head: &std::ops::Range<usize>, start: usize, text: &str) -> bool {
71	    let content = text.trim();
72	    let content_start = start + (text.len() - text.trim_start().len());
73	    !content.is_empty() && head.start <= content_start && content_start + content.len() <= head.end
74	}
75	
76	/// The `parent` cell: the kind and name of the block's parent, such as `class Foo` for a method; `null` for a
77	/// top-level block.
78	fn parent_cell(parent: Option<&crate::types::ParentContext>) -> Value {
79	    opt_cell(parent.map(|p| format!("{} {}", p.kind.as_str(), p.name)).as_deref())
80	}
81	
82	fn search_row(block: &crate::types::RankedBlock) -> [Value; 9] {
83	    [
84	        Value::from(block.block.file.as_str()),
85	        Value::from(block.block.line_start),
86	        Value::from(block.block.line_end),
87	        Value::from(block.block.node_kind.as_str()),
88	        parent_cell(block.block.parent.as_ref()),
89	        opt_cell(block.block.symbol_signature.as_deref()),
90	        opt_cell(snippet(&block.block).as_deref()),
91	        Value::from(block.rank),
92	        Value::from(block.final_score),
93	    ]
94	}
95	
96	const SEARCH_FIELDS: [&str; 9] =
97	    ["file", "lineStart", "lineEnd", "nodeKind", "parent", "symbolSignature", "snippet", "rank", "finalScore"];
98	
99	/// The line `monokl search` prints for each of `blocks`, indentation included and the newline left out.
100	///
101	/// The search budget measures these lines, so a cap counts what the reader receives. Rendering them in one table keeps
102	/// michi's cell quoting and truncation as the only definition of a row.
103	pub fn search_row_texts(blocks: &[RankedBlock]) -> Vec<String> {
104	    let rows: Vec<Vec<Value>> = blocks.iter().map(|block| search_row(block).to_vec()).collect();
105	    let rendered = michi::AgentResponse::new("search").items(rows, SEARCH_FIELDS.as_slice()).render_toon();
106	    rendered.lines().skip(1).map(str::to_owned).collect()
107	}
108	
109	/// Renders a search response as a TOON table of its rows, followed by the truncation count and hints.
110	pub fn render_search(response: &SearchResponse) -> String {
111	    let rows: Vec<Vec<Value>> = response.results.iter().map(|block| search_row(block).to_vec()).collect();
112	    let mut rendered =
113	        michi::AgentResponse::new("search").items(rows, SEARCH_FIELDS.as_slice()).hints(search_hints(response));
114	    if response.truncated {
115	        rendered = rendered.total_count(response.total_blocks_before_truncation);
116	    }
117	    rendered.render_toon()
118	}
119	
120	fn search_hints(response: &SearchResponse) -> Vec<michi::Hint> {
121	    let shown =
122	        michi::TruncationOutcome::new(response.results.iter().collect(), response.total_blocks_before_truncation);
123	    let mut hints: Vec<michi::Hint> = shown.hint(TRUNCATION_GUIDANCE).into_iter().collect();
124	    hints.extend(diagnostic_lines(&response.diagnostics).into_iter().map(michi::Hint::new));
125	    if response.results.is_empty() {
126	        hints.push(michi::Hint::new(
127	            "only declarations and the members of their classes, objects, impls and traits are searched; for text in tests, calls or config try rg",
128	        ));
129	    }
130	    hints
131	}
132	
133	/// One line per distinct diagnostic message; a message tied to files is counted, says what happened to them and names
134	/// the first few.
135	fn diagnostic_lines(diagnostics: &[Diagnostic]) -> Vec<String> {
136	    const LISTED_FILES: usize = 3;
137	    let mut groups: BTreeMap<(&str, Option<&'static str>), Vec<&str>> = BTreeMap::new();
138	    for d in diagnostics {
139	        let verb = d.path.as_ref().map(|_| d.kind.verb());
140	        let paths = groups.entry((d.message.as_str(), verb)).or_default();
141	        paths.extend(d.path.as_deref().map(Utf8Path::as_str));
142	    }
143	    groups
144	        .into_iter()
145	        .map(|((message, verb), mut paths)| match verb {
146	            Some(verb) => {
147	                paths.sort_unstable();
148	                let n = paths.len();
149	                let listed = paths[..n.min(LISTED_FILES)].join(", ");
150	                let more = if n > LISTED_FILES { format!(", ...and {} more", n - LISTED_FILES) } else { String::new() };
151	                format!("{n} {} {verb}: {message}: {listed}{more}", if n == 1 { "file" } else { "files" })
152	            }
153	            None => message.to_owned(),
154	        })
155	        .collect()
156	}
