167	    /// A block whose head is its first line, as for a function whose body opens at the end of that line.
168	    fn block(line_start: usize, code: &str, matched_lines: &[usize]) -> CodeBlock {
169	        let first_line = code.split('\n').next().unwrap_or("");
170	        CodeBlock {
171	            file: Utf8PathBuf::from("src/a.ts"),
