178	            symbol_signature: Some(first_line.trim_end_matches(['{', ' ']).to_owned()),
179	            signature_span: Some(START..START + first_line.len()),
180	            name: None,
181	            matched_lines: matched_lines.to_vec(),
182	            parent: None,
183	        }
