583	fn io_error_code(kind: std::io::ErrorKind) -> michi::ErrorCode {
584	    use michi::ErrorCode;
585	    match kind {
586	        std::io::ErrorKind::NotFound => ErrorCode::NotFound,
587	        std::io::ErrorKind::PermissionDenied => ErrorCode::Forbidden,
588	        std::io::ErrorKind::NotADirectory => ErrorCode::InvalidInput,
589	        _ => ErrorCode::ExternalFailure,
590	    }
591	}
