593	/// Classifies a walk error: an I/O failure by its kind, a bad glob as invalid input, anything else as external.
594	fn walk_error_code(source: &ignore::Error) -> michi::ErrorCode {
595	    match source.io_error() {
596	        Some(io_err) => io_error_code(io_err.kind()),
597	        None if matches!(source, ignore::Error::Glob { .. }) => michi::ErrorCode::InvalidInput,
598	        None => michi::ErrorCode::ExternalFailure,
599	    }
600	}
