637	/// Converts an error into a [`michi::DomainError`] for agent output.
638	pub trait ToDomainError {
639	    /// Returns a short `snake_case` code that is distinct for each error kind.
640	    fn monokl_code(&self) -> &'static str;
641	    /// Converts the error, prefixing the message with [`monokl_code`](Self::monokl_code) and carrying its source chain
642	    /// as causes.
643	    fn to_domain_error(&self) -> michi::DomainError;
644	}
645	
646	impl ToDomainError for MonoklError {
647	    fn monokl_code(&self) -> &'static str {
648	        match self {
649	            MonoklError::Io(_) => "io",
650	            MonoklError::Walk { .. } => "walk",
651	            MonoklError::RegexBuild(_) => "regex_build",
652	            MonoklError::NonUtf8Path { .. } => "non_utf8_path",
653	            MonoklError::TooManyTerms { .. } => "too_many_terms",
654	        }
655	    }
656	
657	    fn to_domain_error(&self) -> michi::DomainError {
658	        use michi::ErrorCode;
659	
660	        let code = match self {
661	            MonoklError::RegexBuild(_) | MonoklError::NonUtf8Path { .. } | MonoklError::TooManyTerms { .. } => {
662	                ErrorCode::InvalidInput
663	            }
664	            MonoklError::Io(err) => io_error_code(err.io_kind()),
665	            MonoklError::Walk { source, .. } => walk_error_code(source),
666	        };
667	
668	        let mut domain_err = michi::DomainError::from_error(code, self).retryable(false);
669	        // Prefixed after from_error, which compares each cause against the unprefixed message to skip repeats.
670	        domain_err.message = format!("{}: {}", self.monokl_code(), domain_err.message);
671	
672	        domain_err = match self {
673	            MonoklError::TooManyTerms { count, limit } => {
674	                domain_err.hint(format!("you supplied {count} terms; the limit is {limit}"))
675	            }
676	            MonoklError::Io(_)
677	            | MonoklError::Walk { .. }
678	            | MonoklError::RegexBuild(_)
679	            | MonoklError::NonUtf8Path { .. } => domain_err,
680	        };
681	
682	        domain_err
683	    }
684	}
