import re
from pathlib import Path

OUT = Path("/tmp/claude-501/leansweep-run")
BASE = {"decl": 59, "quest": 17, "member": 15, "rust": 22, "hq": 32, "hm": 22, "hr": 34, "rhf": 14}
PAT = {
    "decl": r"declaration in top 3: (\d+)/",
    "quest": r"question answer file in top 3: (\d+)/",
    "member": r"member questions: (\d+)/",
    "rust": r"rust hits .*?: (\d+)/\d+ = ",
    "hq": r"held-out questions: (\d+)/",
    "hm": r"held-out members: (\d+)/",
    "hr": r"held-out rust: (\d+)/",
    "rhf": r"report-only react-hook-form: (\d+)/",
}
rows = []
for d in sorted(OUT.iterdir()):
    try:
        rg = (d / "rg.txt").read_text()
        ac = (d / "ac.txt").read_text()
        an = (d / "any.txt").read_text()
    except FileNotFoundError:
        continue
    scores = {k: int(re.search(p, rg).group(1)) for k, p in PAT.items()}
    lost = {k: BASE[k] - v for k, v in scores.items() if v < BASE[k]}
    m = re.search(r"^all\s+222 monokl\s+\S+\s+([\d,]+)\s+([\d,]+)\s+([\d,]+)", ac, re.M)
    med, p90, tot = (int(x.replace(",", "")) for x in m.groups())
    a = re.search(r"^all\s+222 monokl.*?(\d+)/222", an, re.M).group(1)
    rows.append((tot, d.name, med, p90, a, lost, " ".join(f"{k}={v}" for k, v in scores.items())))
for tot, name, med, p90, a, lost, sc in sorted(rows):
    print(f"{name:16} total={tot:8,} med={med:6,} p90={p90:6,} any={a} lost={lost or '-'}  {sc}")

