/// The `price` function, two functions that name it in a parameter or a template, and ten that only call it: thirteen
/// matching blocks in all, the last ten far below the top score.
fn pricing_ts() -> String {
    let mut text = String::from(
        "export function price(item: Item): number {
  return item.cents;
}

\
         export function applyPrice(item: Item, price: number): Item {
  return { ...item, cents: price };
}

\
         export function priceLabel(item: Item): string {
  return `${price(item)} cents`;
}
",
    );
    for letter in 'A'..='J' {
        text.push_str(&format!(
            "
export function list{letter}(items: Item[]): number {{
  return items.map(price).length;
}}
"
        ));
    }
    text.push_str("
export interface Item {
  cents: number;
}
");
    text
}

/// The same shape in Rust.
fn pricing_rs() -> String {
    let mut text = String::from(
        "pub fn price(item: &Item) -> u64 {
    item.cents
}

\
         pub fn apply_price(item: &Item, price: u64) -> Item {
    Item { cents: price, ..*item }
}

\
         pub fn price_label(item: &Item) -> String {
    format!("{} cents", price(item))
}
",
    );
    for letter in 'a'..='j' {
        text.push_str(&format!(
            "
pub fn list_{letter}(items: &[Item]) -> usize {{
    items.iter().map(price).count()
}}
"
        ));
    }
    text.push_str("
pub struct Item {
    pub cents: u64,
}
");
    text

